INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','present-simple','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"present-simple","title":"Present simple","level":"A1","order":10,"summary":"Talk about regular activities and practise agreement, negatives, questions and base forms.","learningGoals":["Habits and facts","Spelling","Do and does"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Habits and facts","explanation":"Use the present simple for routines and general facts. With I, you, we and they, use the base verb. Most singular third-person subjects add -s.","examples":["We cycle to college.","The guide explains the route."]},{"title":"Spelling","explanation":"Some verbs add -es. A consonant followed by y usually changes to -ies; a vowel followed by y keeps the y.","examples":["She carries the equipment.","He plays chess."]},{"title":"Do and does","explanation":"Use do or does for questions, and do not or does not for negatives. The main verb then returns to its base form.","examples":["Does the driver stop here?","We do not work on Sundays."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-present","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"cd10e053-87af-5735-abb2-6b7b1c5cd482","topicSlug":"present-simple","level":"A1","prompt":"Every week, I ____ dinner in the kitchen. Use the present simple.","choices":[{"id":"A","text":"cooking"},{"id":"B","text":"cook"},{"id":"C","text":"cooks"},{"id":"D","text":"cooked"}],"answerId":"B","hint":"Use the present simple for routines and general facts. With I, you, we and they, use the base verb. Most singular third-person subjects add -s. Focus on **affirmative** in this question.","explanation":"For the routine described, “I” takes cook. Use the base form with this subject.","keywords":[],"source":"seed","skill":"affirmative","contextKey":"verb-cook","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-present","pcc-esol"],"version":"foundations-2026-09-v1","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"8ef9a4ebb74123ea735833384aaf7913fb696eeb4a30c986d8851f5ced12fe96","teaching":{"steps":["Identify what the question tests: **affirmative**. Use the present simple for routines and general facts. With I, you, we and they, use the base verb. Most singular third-person subjects add -s.","For the routine described, “I” takes cook. Use the base form with this subject.","Choose **cook**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**cooking** is the -ing form. It cannot fill the finite simple-tense or base-after-auxiliary slot requested here. For the routine described, “I” takes cook. Use the base form with this subject.","B":"For the routine described, “I” takes cook. Use the base form with this subject.","C":"**cooks** does not give the present-simple form for this subject. For the routine described, “I” takes cook. Use the base form with this subject.","D":"**cooked** does not give the present-simple form for this subject. For the routine described, “I” takes cook. Use the base form with this subject."}}},{"id":"5ba0cf86-da70-5414-ab0e-a26f957009b5","topicSlug":"present-simple","level":"A1","prompt":"Complete the present-simple negative: I ____ cook dinner in the kitchen.","choices":[{"i